CREATE TABLE public.search_projections(tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,document_id uuid NOT NULL,index_version integer NOT NULL,projection_version integer NOT NULL DEFAULT 1,status varchar(16) NOT NULL DEFAULT 'pending',chunk_count integer NOT NULL DEFAULT 0,checksum char(64),requested_at timestamptz NOT NULL DEFAULT now(),projected_at timestamptz,last_error_code varchar(80),PRIMARY KEY(tenant_id,document_id,index_version));
ALTER TABLE public.search_projections ENABLE ROW LEVEL SECURITY;ALTER TABLE public.search_projections FORCE ROW LEVEL SECURITY;CREATE POLICY search_projections_tenant_isolation ON public.search_projections USING(tenant_id=NULLIF(current_setting('app.current_tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.current_tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON public.search_projections TO cortex_app;
CREATE TABLE public.search_reconciliation_runs(id bigserial PRIMARY KEY,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status varchar(16) NOT NULL DEFAULT 'running',missing_count integer NOT NULL DEFAULT 0,stale_count integer NOT NULL DEFAULT 0,error_code varchar(80));GRANT SELECT,INSERT,UPDATE ON public.search_reconciliation_runs TO cortex_app;GRANT USAGE,SELECT ON SEQUENCE public.search_reconciliation_runs_id_seq TO cortex_app;
